input.command:
cd "/Users/smaschek/dev/paigasus/paigasus-core"
echo "=== git state ===" && git status --short && echo "(clean if blank)" && git log origin/feature/sma-436-fix-pytypecheck-vacuous-pass-basedpyright-checks-zero-files..HEAD --oneline && echo "(no unpushed if blank)"
echo ""
echo "=== AGENTS.md present? ===" && ls AGENTS.md 2>/dev/null || echo "no AGENTS.md (CLAUDE.md is the project instructions)"
echo ""
owner=$(gh repo view --json owner --jq '.owner.login')
repo=$(gh repo view --json name --jq '.name')
echo "owner=$owner repo=$repo"
OUT="$CLAUDE_JOB_DIR/tmp/cr_threads_r1.json"
gh api graphql -F owner="$owner" -F repo="$repo" -F pr=53 -f query='query($owner:String!, $repo:String!, $pr:Int!) {
  repository(owner:$owner, name:$repo) {
    pullRequest(number:$pr) {
      title
      reviewThreads(first:100) {
        nodes {
          id
          isResolved
          isOutdated
          comments(first:10) {
            nodes { databaseId body path line startLine originalLine author { login } }
          }
        }
      }
    }
  }
}' > "$OUT"
echo "saved to $OUT"
echo ""
echo "=== thread summary (all) ==="
jq -r '.data.repository.pullRequest.reviewThreads.nodes[] | "thread=\(.id[-8:]) resolved=\(.isResolved) outdated=\(.isOutdated) author=\(.comments.nodes[0].author.login) path=\(.comments.nodes[0].path):\(.comments.nodes[0].line)"' "$OUT"
echo ""
echo "=== count of actionable (unresolved, not outdated, coderabbit) ==="
jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false and .isOutdated==false and (.comments.nodes[0].author.login | test("coderabbit";"i")))] | length' "$OUT"

cd "/Users/smaschek/dev/paigasus/paigasus-core"
TMP="$CLAUDE_JOB_DIR/tmp"
declare -A THREADS=( [T1]="PRRT_kwDOSoEBbM6LAaVF" [T2]="PRRT_kwDOSoEBbM6LAaVH" [T3]="PRRT_kwDOSoEBbM6LAaVI" )
declare -A FILES=( [T1]="$TMP/reply_t1.md" [T2]="$TMP/reply_t2.md" [T3]="$TMP/reply_t3.md" )

for k in T1 T2 T3; do
  tid="${THREADS[$k]}"
  body=$(cat "${FILES[$k]}")
  echo "=== $k thread=$tid ==="
  echo "--- reply ---"
  gh api graphql -f threadId="$tid" -f body="$body" -f query='mutation($threadId:ID!, $body:String!){
    addPullRequestReviewThreadReply(input:{pullRequestReviewThreadId:$threadId, body:$body}){
      comment { databaseId url }
    }
  }' --jq '.data.addPullRequestReviewThreadReply.comment | "replied: \(.url)"'
  echo "--- resolve ---"
  gh api graphql -f threadId="$tid" -f query='mutation($threadId:ID!){
    resolveReviewThread(input:{threadId:$threadId}){ thread { isResolved } }
  }' --jq '.data.resolveReviewThread.thread | "resolved=\(.isResolved)"'
done
